<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { httpClient } from '@/shared/http/client'
const props=defineProps<{caseId:string;category:'SHOP_QUOTE'|'LOSS_ASSESSMENT';assignmentVersion?:number}>()
const emit=defineEmits<{candidate:[value:Record<string,unknown>];changed:[];ready:[value:boolean]}>()
interface Job {id:string;fileId:string;state:string;provider:string;errorCode?:string;reviewVersion:number;confirmed:boolean;candidate?:Record<string,unknown>}
interface Attachment {id:string;name:string;category:string;state:string}
const job=ref<Job>(),files=ref<Attachment[]>([]),selected=ref<File>(),busy=ref(false),message=ref(''),preview=ref(''),contentType=ref(''),progress=ref(0),provider=ref(''),uploadKey=ref(crypto.randomUUID()),page=ref(1),total=ref(0)
const pendingReview=ref<{body:string;key:string}>()
const ready=computed(()=>!busy.value&&Boolean(preview.value&&job.value&&['SUCCEEDED','FAILED'].includes(job.value.state)))
watch(ready,value=>emit('ready',value),{immediate:true})
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
const data=async<T>(url:string,body?:unknown)=>body===undefined?(await httpClient.get<{data:T}>(url)).data.data:(await httpClient.post<{data:T}>(url,body)).data.data
async function load(){const result=await data<{records:Attachment[];total:number}>(`/materials/cases/${props.caseId}?page=${page.value}&size=20`);files.value=result.records.filter(f=>f.category===props.category&&f.state==='ACTIVE');total.value=result.total;provider.value=(await data<{provider:string}>('/ocr/configuration')).provider}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;message.value='';try{await action()}catch(error){message.value=error instanceof Error?error.message:'处理失败'}finally{busy.value=false}}
function choose(event:Event){selected.value=(event.target as HTMLInputElement).files?.[0];uploadKey.value=crypto.randomUUID()}
async function showOriginal(fileId:string){const response=await httpClient.get<Blob>(`/materials/${fileId}/download`,{responseType:'blob'});if(disposed)return;if(preview.value)URL.revokeObjectURL(preview.value);contentType.value=response.data.type;preview.value=URL.createObjectURL(response.data)}
async function poll(){if(!job.value||disposed)return;const result=await data<Job>(`/ocr/${job.value.id}`);if(disposed)return;job.value=result;if(['QUEUED','RUNNING'].includes(result.state))timer=setTimeout(()=>void run(poll),1800);else if(result.candidate)emit('candidate',result.candidate)}
async function recognize(fileId:string){if(timer)clearTimeout(timer);pendingReview.value=undefined;job.value=undefined;await showOriginal(fileId);job.value=await data<Job>('/ocr',{fileId,simulateFailure:false});await poll()}
async function upload(){if(!selected.value)throw Error('请选择原件');const body=new FormData();body.append('file',selected.value);body.append('category',props.category);if(props.assignmentVersion)body.append('assignmentVersion',String(props.assignmentVersion));const result=(await httpClient.post<{data:{id:string}}>(`/materials/cases/${props.caseId}`,body,{headers:{'Content-Type':undefined,'Idempotency-Key':uploadKey.value},onUploadProgress:e=>{progress.value=e.total?Math.round(e.loaded/e.total*100):0}})).data.data;emit('changed');await load();await recognize(result.id)}
async function confirm(adopted:unknown,fields:Record<string,string>={}){
  if(busy.value)throw Error('原件上传或识别处理中，请稍后')
  if(!job.value||!['SUCCEEDED','FAILED'].includes(job.value.state))throw Error('请先识别原件，任务结束后可核对或人工补录');
  if(!preview.value)throw Error('请先加载并查看原件');
  if(job.value.reviewVersion>0&&job.value.candidate?.originalReviewed===true&&JSON.stringify(job.value.candidate.adopted)===JSON.stringify(adopted)&&JSON.stringify(job.value.candidate.fields)===JSON.stringify(fields)){job.value=await data<Job>(`/ocr/${job.value.id}/confirm`,{expectedVersion:job.value.reviewVersion});return {jobId:job.value.id,revision:job.value.reviewVersion}}
  const candidate={...job.value.candidate,fields,adopted,originalReviewed:true};
  const body={expectedVersion:job.value.reviewVersion,candidate},serialized=JSON.stringify(body);if(pendingReview.value?.body!==serialized)pendingReview.value={body:serialized,key:crypto.randomUUID()};
  job.value=(await httpClient.post<{data:Job}>(`/ocr/${job.value.id}/review`,body,{headers:{'Idempotency-Key':pendingReview.value.key}})).data.data;pendingReview.value=undefined;
  job.value=await data<Job>(`/ocr/${job.value.id}/confirm`,{expectedVersion:job.value.reviewVersion});return {jobId:job.value.id,revision:job.value.reviewVersion}
}
defineExpose({confirm})
watch(()=>props.caseId,()=>{if(timer)clearTimeout(timer);job.value=undefined;page.value=1;void run(load)})
onMounted(()=>void run(load));onUnmounted(()=>{disposed=true;emit('ready',false);if(timer)clearTimeout(timer);if(preview.value)URL.revokeObjectURL(preview.value)})
</script>
<template><section class="recognition"><header><h3>{{ category==='SHOP_QUOTE'?'报价原件':'核损原件' }}</h3><span class="provider">{{ provider==='MOCK_V1'?'模拟识别 · 请人工核对':provider==='BAIDU_HANDWRITING_V1'?'百度识别':'读取识别配置' }}</span></header><p role="alert" v-if="message">{{ message }}</p><FileDropZone hint="一次1个PDF/JPG/JPEG/PNG，≤10 MiB；选择后仍需点击“上传并识别”。百度模式仅支持图片。" :max-bytes="10485760" :feedback="message" :status="job?.state==='SUCCEEDED'?'success':'pending'" :disabled="busy" :busy="busy"><label class="file-label">添加原件<input type="file" accept=".pdf,.jpg,.jpeg,.png" :disabled="busy" @change="choose"/></label></FileDropZone><button type="button" :disabled="busy||!selected" @click="run(upload)">{{ busy?'正在处理…':'上传并识别' }}</button><progress v-if="busy&&progress" :value="progress" max="100" aria-label="上传进度"/><p class="hint">PDF / JPG / PNG · 10 MiB；识别失败可人工补录。百度模式仅识别图片。</p><ul><li v-for="file in files" :key="file.id"><span>{{ file.name }}</span><button :disabled="busy" @click="run(()=>recognize(file.id))">查看与识别</button></li></ul><div v-if="total>20" class="pages"><button :disabled="busy||page===1" @click="page--;run(load)">上一页</button><span>第 {{ page }} 页</span><button :disabled="busy||page*20>=total" @click="page++;run(load)">下一页</button></div><template v-if="job"><p role="status">{{ ['QUEUED','RUNNING'].includes(job.state)?'正在识别，可先阅读原件':job.state==='FAILED'?'识别失败，请人工补录并核对原件':'候选已生成，请核对采用信息' }}<span v-if="job.errorCode"> · {{ job.errorCode }}</span></p><img v-if="preview&&contentType.startsWith('image/')" :src="preview" alt="受控原件预览"/><a v-if="preview" :href="preview" :download="'原件'+(contentType==='image/jpeg'?'.jpg':contentType==='image/png'?'.png':'.pdf')">下载原件核对</a><iframe v-if="preview&&!contentType.startsWith('image/')" :src="preview" title="受控原件预览"/><details v-if="job.candidate"><summary>原始候选信息</summary><pre>{{ JSON.stringify(job.candidate,null,2) }}</pre></details><p v-if="preview">提交采用信息即确认已核对原件与当前采用信息。</p></template></section></template>
<style scoped>.recognition{border-top:1px solid #d9e2e2;padding:20px 0}.recognition header{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.recognition h3{margin:0;font-size:17px}.provider,.hint{font-size:12px;color:#566a70}.recognition label{display:block;margin:14px 0 8px}.recognition button{margin:6px 8px 6px 0}.recognition ul{padding:0;list-style:none}.recognition li{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;border-bottom:1px solid #e0e7e7;padding:8px 0}.recognition img,.recognition iframe{width:100%;max-height:380px;object-fit:contain;border:1px solid #d9e2e2;background:#f5f7f7}.recognition iframe{height:380px}.recognition pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.recognition input[type=file]{display:block;margin-top:8px;max-width:100%}.recognition progress{width:100%}</style>
